"""Glue-opcode report: ``glue_opcodes_autogenerated_report.md``."""

from __future__ import annotations

from pathlib import Path

import numpy as np
import pandas as pd

from evm_gasfit.config import Config
from evm_gasfit.glue.required import PRICED_GLUE_SPECS
from evm_gasfit.modeling.results import NNLSResults

from .plots import (
    plot_glue_bootstrap,
    plot_glue_diagnostics,
    plot_glue_regression,
    slug,
)

_TIER_BY_NAME: dict[str, str] = {s.name: s.tier for s in PRICED_GLUE_SPECS}


def _anchor(text: str) -> str:
    """GitHub-flavored anchor for a heading text."""
    out = []
    for ch in text.lower():
        if ch.isalnum() or ch == "-":
            out.append(ch)
        elif ch in " _":
            out.append("-")
    return "".join(out)


def _fmt(value, ndigits: int = 4) -> str:
    if value is None:
        return "n/a"
    if isinstance(value, float) and np.isnan(value):
        return "n/a"
    if isinstance(value, float):
        return f"{value:.{ndigits}g}"
    return str(value)


def _fmt_pvalue(value, ndigits: int = 2) -> str:
    if value is None:
        return "n/a"
    if isinstance(value, float) and np.isnan(value):
        return "n/a"
    if isinstance(value, float):
        return f"{value:.{ndigits}e}"
    return str(value)


def _headline_table(rows: list[pd.Series]) -> list[str]:
    """Render a compact metrics table for a list of glue-result rows."""
    lines = [
        "| glue_opcode | nobs | glue_runtime_ms | p_value | rsquared |",
        "| --- | --- | --- | --- | --- |",
    ]
    for row in rows:
        nobs = row.get("nobs")
        nobs_cell = str(int(nobs)) if not pd.isna(nobs) else "n/a"
        lines.append(
            f"| `{row['glue_opcode']}` | {nobs_cell} | "
            f"{_fmt(row.get('glue_runtime_ms'))} | "
            f"{_fmt_pvalue(row.get('p_value'))} | "
            f"{_fmt(row.get('rsquared'))} |"
        )
    return lines


def _emit_opcode_block(
    lines: list[str],
    *,
    row: pd.Series,
    fit: NNLSResults | None,
    client: str,
    glue_opcode: str,
    plots_enabled: bool,
    out_dir: Path,
    show_summary: bool,
) -> None:
    """Write the per-opcode collapsible (headline summary + plots)."""
    nobs_cell = str(int(row["nobs"])) if not pd.isna(row.get("nobs")) else "n/a"
    summary_line = (
        f"<code>{glue_opcode}</code> · "
        f"nobs={nobs_cell} · "
        f"runtime_ms={_fmt(row.get('glue_runtime_ms'))} · "
        f"p={_fmt_pvalue(row.get('p_value'))} · "
        f"R²={_fmt(row.get('rsquared'))}"
    )
    lines.append(f"<details><summary>{summary_line}</summary>")
    lines.append("")

    if fit is not None and show_summary:
        lines.append("```")
        lines.append(fit.summary())
        lines.append("```")
        lines.append("")

    if fit is not None and plots_enabled:
        plot_glue_regression(
            fit, glue_opcode=glue_opcode, client=client, out_dir=out_dir
        )
        plot_glue_bootstrap(
            fit, glue_opcode=glue_opcode, client=client, out_dir=out_dir
        )
        plot_glue_diagnostics(
            fit, glue_opcode=glue_opcode, client=client, out_dir=out_dir
        )
        base = slug(glue_opcode, client)
        for family in ("regression", "bootstrap", "diagnostics"):
            lines.append(f"![](figs/glue/{base}__{family}.png)")
            lines.append("")

    lines.append("</details>")
    lines.append("")


def write_glue_report(
    out_dir: Path,
    glue_results_df: pd.DataFrame,
    glue_fits: dict[tuple[str, str], NNLSResults],
    config: Config,
) -> None:
    """Write the glue-opcode markdown report under ``out_dir``."""
    out_path = out_dir / "glue_opcodes_autogenerated_report.md"
    plots_enabled = config.output.plots

    lines: list[str] = ["# Glue opcodes report", ""]
    if glue_results_df.empty:
        out_path.write_text("\n".join(lines))
        return

    lines.append(
        "Per-client NNLS fits of priced glue opcodes against their driver "
        "fixtures. Cycle-tier opcodes share one joint regression per client "
        "(shown once); pure-tier and mixed-tier opcodes each get a "
        "single-feature fit. Mixed-tier fits pre-adjust the LHS by "
        "subtracting the contribution of every priced upstream partner "
        "selected by the detector (pure ∪ cycle for `mixed_a`, plus "
        "`mixed_a` for `mixed_b`)."
    )
    lines.append("")

    clients = sorted(glue_results_df["client_name"].unique())

    # TOC.
    lines.append(
        "**Contents:** " + " · ".join(f"[{c}](#{_anchor(c)})" for c in clients)
    )
    lines.append("")

    for client in clients:
        lines.append(f"## {client}")
        lines.append("")

        client_rows = list(
            glue_results_df[glue_results_df["client_name"] == client]
            .reset_index(drop=True)
            .iterrows()
        )
        client_rows = [row for _, row in client_rows]

        pure_rows = [
            r for r in client_rows if _TIER_BY_NAME.get(str(r["glue_opcode"])) == "pure"
        ]
        cycle_rows = [
            r
            for r in client_rows
            if _TIER_BY_NAME.get(str(r["glue_opcode"])) == "cycle"
        ]
        mixed_a_rows = [
            r
            for r in client_rows
            if _TIER_BY_NAME.get(str(r["glue_opcode"])) == "mixed_a"
        ]
        mixed_b_rows = [
            r
            for r in client_rows
            if _TIER_BY_NAME.get(str(r["glue_opcode"])) == "mixed_b"
        ]

        # Headline metrics for the whole client.
        lines.extend(_headline_table(client_rows))
        lines.append("")

        # Cycle tier — joint fit shared across opcodes.
        if cycle_rows:
            lines.append(f"### Cycle glue — joint fit · {client}")
            lines.append("")

            # Find the shared fit object (same id for all cycle opcodes).
            joint_fit: NNLSResults | None = None
            for r in cycle_rows:
                fit = glue_fits.get((client, str(r["glue_opcode"])))
                if fit is not None:
                    joint_fit = fit
                    break

            if joint_fit is not None:
                lines.append(
                    "<details><summary>Joint NNLS regression summary</summary>"
                )
                lines.append("")
                lines.append("```")
                lines.append(joint_fit.summary())
                lines.append("```")
                lines.append("")
                lines.append("</details>")
                lines.append("")

            for row in cycle_rows:
                glue_opcode = str(row["glue_opcode"])
                fit = glue_fits.get((client, glue_opcode))
                _emit_opcode_block(
                    lines,
                    row=row,
                    fit=fit,
                    client=client,
                    glue_opcode=glue_opcode,
                    plots_enabled=plots_enabled,
                    out_dir=out_dir,
                    show_summary=False,  # joint summary already shown above
                )

        # Pure tier — one fit each.
        if pure_rows:
            lines.append(f"### Pure glue · {client}")
            lines.append("")
            for row in pure_rows:
                glue_opcode = str(row["glue_opcode"])
                fit = glue_fits.get((client, glue_opcode))
                _emit_opcode_block(
                    lines,
                    row=row,
                    fit=fit,
                    client=client,
                    glue_opcode=glue_opcode,
                    plots_enabled=plots_enabled,
                    out_dir=out_dir,
                    show_summary=True,
                )

        # Mixed-A tier — single-feature fit, partners drawn from pure + cycle.
        if mixed_a_rows:
            lines.append(f"### Mixed glue (tier A) · {client}")
            lines.append("")
            for row in mixed_a_rows:
                glue_opcode = str(row["glue_opcode"])
                fit = glue_fits.get((client, glue_opcode))
                _emit_opcode_block(
                    lines,
                    row=row,
                    fit=fit,
                    client=client,
                    glue_opcode=glue_opcode,
                    plots_enabled=plots_enabled,
                    out_dir=out_dir,
                    show_summary=True,
                )

        # Mixed-B tier — also allows mixed-A partners.
        if mixed_b_rows:
            lines.append(f"### Mixed glue (tier B) · {client}")
            lines.append("")
            for row in mixed_b_rows:
                glue_opcode = str(row["glue_opcode"])
                fit = glue_fits.get((client, glue_opcode))
                _emit_opcode_block(
                    lines,
                    row=row,
                    fit=fit,
                    client=client,
                    glue_opcode=glue_opcode,
                    plots_enabled=plots_enabled,
                    out_dir=out_dir,
                    show_summary=True,
                )

    out_path.write_text("\n".join(lines))
